'use strict';
(function(root){
 function windowFor(total,page=1,size=25){total=Math.max(0,Math.trunc(Number(total)||0));size=[10,25,50,100].includes(Number(size))?Number(size):25;const pages=Math.max(1,Math.ceil(total/size));page=Math.max(1,Math.min(pages,Math.trunc(Number(page)||1)));const start=(page-1)*size;return {total,page,size,pages,start,end:Math.min(total,start+size)};}
 if(typeof module==='object'&&module.exports)module.exports={windowFor};
 if(typeof document==='undefined')return;
 const nodes=new WeakMap(),active=new Set(),memory=new Map();let scheduled=false;
 function hash(value){let n=2166136261;for(let i=0;i<value.length;i++){n^=value.charCodeAt(i);n=Math.imul(n,16777619);}return (n>>>0).toString(36);}
 function context(el){const modal=el.closest('dialog'),section=el.closest('section'),title=modal?.querySelector('h2')?.textContent||'';return [typeof appState==='undefined'?'':appState.route,typeof appState==='undefined'?'':appState.tab,title,section?.querySelector('h2')?.textContent||''].join('|');}
 function external(el){return !!el.closest('#charles-history')||(!el.closest('dialog')&&el.closest('#crm-content')&&(document.querySelector('.crm-pager')||typeof crmState!=='undefined'&&['customers','agenda','communications','pipeline'].includes(crmState.tab)));}
 function controls(entry){const w=windowFor(entry.rows.length,entry.state.page,entry.state.size);entry.state.page=w.page;entry.rows.forEach((r,i)=>r.classList.toggle('page-hidden',i<w.start||i>=w.end));entry.pager.hidden=entry.rows.length===0||(w.total<=10&&!entry.el.classList.contains('table-wrap'));if(w.total<=10){entry.pager.innerHTML=`<span class="page-count">${w.total} ${w.total===1?'registro':'registros'}</span>`;return;}entry.pager.innerHTML=`<span class="page-count" role="status">${w.total?w.start+1:0}–${w.end} de ${w.total} registros</span><label class="page-size">Por página <select aria-label="Registros por página">${[10,25,50,100].map(n=>`<option value="${n}"${n===w.size?' selected':''}>${n}</option>`).join('')}</select></label><div class="page-buttons"><button type="button" data-page="1" aria-label="Primera página" ${w.page===1?'disabled':''}>«</button><button type="button" data-page="${w.page-1}" aria-label="Página anterior" ${w.page===1?'disabled':''}>Anterior</button><span>Página ${w.page} de ${w.pages}</span><button type="button" data-page="${w.page+1}" aria-label="Página siguiente" ${w.page===w.pages?'disabled':''}>Siguiente</button><button type="button" data-page="${w.pages}" aria-label="Última página" ${w.page===w.pages?'disabled':''}>»</button></div>`;}
 function attach(el,rows,ordinal){const old=nodes.get(el);if(!rows.length||external(el)){if(old){old.pager.remove();old.state.page=1;active.delete(old);nodes.delete(el);}return;}if(old&&old.rows.length===rows.length&&old.rows.every((r,i)=>r===rows[i]))return;
 if(old){active.delete(old);old.pager.remove();old.rows.forEach(r=>r.classList.remove('page-hidden'));}
 const key=context(el)+'|'+(el.id||el.className)+'|'+(el.querySelector('thead')?.textContent||'')+'|'+ordinal,fingerprint=hash(rows.map(r=>r.innerHTML).join('|')),saved=memory.get(key),state=saved?.fingerprint===fingerprint?saved:{page:1,size:saved?.size||25,fingerprint};memory.set(key,state);if(memory.size>120)memory.delete(memory.keys().next().value);
 const pager=document.createElement('nav');pager.className='list-pagination';pager.setAttribute('aria-label','Paginación del listado');el.insertAdjacentElement('afterend',pager);const entry={el,rows,pager,state};nodes.set(el,entry);active.add(entry);pager.addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(!b||b.disabled)return;state.page=Number(b.dataset.page);controls(entry);const top=el.getBoundingClientRect().top;if(top<0){el.scrollIntoView({block:'start',behavior:'instant'});}(pager.querySelector('[aria-label="Página siguiente"]:not(:disabled)')||pager.querySelector('[aria-label="Página anterior"]:not(:disabled)'))?.focus({preventScroll:true});});pager.addEventListener('change',e=>{if(e.target.tagName!=='SELECT')return;state.size=Number(e.target.value);state.page=1;controls(entry);pager.querySelector('select')?.focus({preventScroll:true});});controls(entry);
 }
 function scan(){scheduled=false;observer.disconnect();try{for(const entry of active){if(!entry.el.isConnected||entry.rows.every(r=>!entry.el.contains(r))){entry.pager.remove();if(entry.el.isConnected)entry.state.page=1;nodes.delete(entry.el);active.delete(entry);}}const ordinals=new Map();for(const el of document.querySelectorAll('.table-wrap,#catalog,.metals-grid,#global-results,.commercial-column,[data-paginate]')){const table=el.classList.contains('table-wrap'),rows=table?[...el.querySelectorAll(':scope > table > tbody > tr')]:[...el.children].filter(r=>r.matches('.product,.metal-card,.search-result,.crm-deal,[data-page-item]'));const scope=context(el)+'|'+(table?el.querySelector('thead')?.textContent:el.className),i=ordinals.get(scope)||0;ordinals.set(scope,i+1);if(table){el.tabIndex=0;el.setAttribute('aria-label','Tabla de registros; desplázate horizontalmente para ver todas las columnas');}attach(el,rows,i);}
 const parents=new Set([...document.querySelectorAll('.list-item,.crm-entry,.notification')].map(r=>r.parentElement));for(const el of parents){if(el.closest('.cart,.receipt,.sidebar'))continue;attach(el,[...el.children].filter(r=>r.matches('.list-item,.crm-entry,.notification')),0);}
 const d=document.querySelector('#dialog');if(d)d.classList.toggle('modal-wide',!!d.querySelector('table,.kpis,.detail-grid'));
 }finally{observer.observe(document.body,{childList:true,subtree:true});}}
 const observer=new MutationObserver(()=>{if(!scheduled){scheduled=true;requestAnimationFrame(scan);}});observer.observe(document.body,{childList:true,subtree:true});scan();
 document.addEventListener('click',e=>{if(e.target.closest('[data-action="logout"]'))memory.clear();});
 root.AureaPagination={windowFor,refresh:scan};
})(typeof window==='undefined'?globalThis:window);
